// GOOD: Proper use of the JDBC API (parameterized query)
import java.io.IOException;
import java.sql.*;
import javax.servlet.http.*;

public class UserLookupServlet extends HttpServlet {
    private static final String DB_URL = "jdbc:mysql://localhost/appdb";

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        // Untrusted input taken from the request
        String username = req.getParameter("username");

        // Validate input before using it (basic allow-list check)
        if (username == null || !username.matches("[A-Za-z0-9_]{1,30}")) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid username");
            return;
        }

        // The SQL structure is fixed; the user value is bound as a parameter
        String sql = "SELECT id, email FROM users WHERE username = ?";

        try (Connection conn = DriverManager.getConnection(DB_URL, "app", "secret");
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setString(1, username); // The driver treats this strictly as data, not SQL

            try (ResultSet rs = ps.executeQuery()) {
                resp.setContentType("text/plain;charset=UTF-8"); // Not interpreted as HTML
                while (rs.next()) {
                    resp.getWriter().println("User: " + rs.getString("email"));
                }
            }
        } catch (SQLException e) {
            // Log details on the server and return only a generic message to the client
            getServletContext().log("Database error during user lookup", e);
            resp.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Internal error");
        }
    }
}
